<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WINDELS AI OS</title><style>body{font:16px system-ui;margin:0;background:#080b14;color:#e8edff}.box{max-width:520px;margin:10vh auto;padding:32px;background:#12182a;border:1px solid #27304c;border-radius:16px}input,button{box-sizing:border-box;width:100%;padding:13px;margin:7px 0;border-radius:8px;border:1px solid #36415f;background:#0b1020;color:#fff}button{background:#665cff;font-weight:700;cursor:pointer}.muted{color:#9ba8ca}#message{white-space:pre-wrap}</style></head><body><main class="box"><h1>WINDELS AI OS</h1><p class="muted">Portable CodeIgniter application</p><form id="login"><input id="email" type="email" placeholder="Email" required><input id="password" type="password" placeholder="Password" required><button>Sign in</button></form><p id="message"></p></main><script>login.onsubmit=async(e)=>{e.preventDefault();message.textContent='Signing in…';try{const r=await fetch('api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,password:password.value})});const b=await r.json();if(!r.ok)throw Error(b.error?.message||'Login failed');localStorage.setItem('windels-auth',JSON.stringify({state:{accessToken:b.data.token,refreshToken:b.data.refreshToken,user:b.data.user}}));message.textContent='Signed in successfully. The PHP API is ready.'}catch(x){message.textContent=x.message}}</script></body></html>
